const DEFAULT_META = {level:1,survivalLevel:1,xp:0,coins:0,bestRank:'D',totalKOs:0,bestCombo:0,shifts:0,freeCrates:0,unlockedBats:['STANDARD'],unlockedSkins:['CLASSIC','POTATO'],unlockedMaps:['FLOOR 13'],selectedBat:'STANDARD',selectedSkin:'POTATO',selectedMap:'FLOOR 13',cameraMode:'OFFICE CAM',selectedColor:'#b9833d',survivalBestWave:0,contentVersion:'2.7',settings:{moveSpeed:2.2,smoothTurnSpeed:110,haptics:true,music:true}};
function loadMeta(){
  try{
    const raw=localStorage.getItem('crazyOfficeNightShiftMeta');
    const parsed=raw?JSON.parse(raw):{};
    const upgrading=parsed.contentVersion!=='2.6';
    const merged={...DEFAULT_META,...parsed,settings:{...DEFAULT_META.settings,...(parsed.settings||{})}};
    if(upgrading && !OWNER_MODE){merged.unlockedBats=['STANDARD'];merged.unlockedSkins=['CLASSIC','POTATO'];merged.unlockedMaps=['FLOOR 13'];merged.selectedBat='STANDARD';merged.selectedSkin='POTATO';merged.selectedMap='FLOOR 13';}
    merged.unlockedBats=Array.from(new Set(merged.unlockedBats||['STANDARD']));
    merged.unlockedSkins=Array.from(new Set(merged.unlockedSkins||['CLASSIC','POTATO']));
    merged.unlockedMaps=Array.from(new Set(merged.unlockedMaps||['FLOOR 13']));
    merged.survivalLevel=Math.max(1,Number(merged.survivalLevel||1));merged.contentVersion='2.7';
    if(upgrading)try{localStorage.setItem('crazyOfficeNightShiftMeta',JSON.stringify(merged));}catch{}
    return merged;
  }catch(e){console.warn('Meta save could not be read; using defaults.',e);return {...DEFAULT_META,settings:{...DEFAULT_META.settings}};}
}


