function ownedIds(kind){if(OWNER_MODE)return (kind==='bat'?CATALOG.bats:kind==='skin'?CATALOG.skins:CATALOG.maps).map(x=>x.id);return kind==='bat'?G.meta.unlockedBats:kind==='skin'?G.meta.unlockedSkins:G.meta.unlockedMaps;}
function normalizeMetaSelection(){
  if(OWNER_MODE){G.meta.unlockedBats=CATALOG.bats.map(x=>x.id);G.meta.unlockedSkins=CATALOG.skins.map(x=>x.id);G.meta.unlockedMaps=CATALOG.maps.map(x=>x.id);}
  G.meta.unlockedBats=(G.meta.unlockedBats||[]).filter(id=>CATALOG.bats.some(x=>x.id===id));
  G.meta.unlockedSkins=(G.meta.unlockedSkins||[]).filter(id=>CATALOG.skins.some(x=>x.id===id));
  G.meta.unlockedMaps=(G.meta.unlockedMaps||[]).filter(id=>CATALOG.maps.some(x=>x.id===id));
  if(!G.meta.unlockedBats.length)G.meta.unlockedBats=['STANDARD'];if(!G.meta.unlockedSkins.length)G.meta.unlockedSkins=['POTATO'];if(!G.meta.unlockedMaps.length)G.meta.unlockedMaps=['FLOOR 13'];
  if(!ownedIds('bat').includes(G.meta.selectedBat))G.meta.selectedBat=ownedIds('bat')[0];
  if(!ownedIds('skin').includes(G.meta.selectedSkin))G.meta.selectedSkin=ownedIds('skin')[0];
  if(!ownedIds('map').includes(G.meta.selectedMap))G.meta.selectedMap=ownedIds('map')[0];saveMeta();
}
normalizeMetaSelection();
